print(allPositive([2, 0]))

key:
func allPositive(_ values: [Int]) -> Bool {
    for value in values { if value <= 0 { return false } }
    return true
}
assert(allPositive([2, 3]))
assert(!allPositive([2, 0]))
assert(allPositive([]))

Ноль нарушает строгое >0, поэтому отвергаем <=0. Пустой вход проходит выбранное универсальное условие.

func firstOddIndex(_ values: [Int]) -> Int? {
    for index in values.indices where values[index] % 2 != 0 { return index }
    return nil
}
assert(firstOddIndex([2, 6, -3, 1]) == 2)
assert(firstOddIndex([2, 4]) == nil)
assert(firstOddIndex([]) == nil)

Сохраняется первый подходящий индекс, отсутствие — Optional. Для отрицательных проверяем остаток !=0, не ==1.

func hasAdjacentDuplicate(_ values: [Int]) -> Bool {
    guard values.count > 1 else { return false }
    for index in 1..<values.count {
        if values[index] == values[index - 1] { return true }
    }
    return false
}
assert(hasAdjacentDuplicate([1, 2, 2]))
assert(!hasAdjacentDuplicate([1, 2, 1]))
assert(!hasAdjacentDuplicate([]))
assert(!hasAdjacentDuplicate([1]))

